#Requires -Version 7.0
[CmdletBinding(SupportsShouldProcess)]
param([ValidateSet('Write','Finish')][string]$Operation='Write')
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$workspace='<repo>'
$directory=Join-Path $workspace 'docs/evidence/release15/ui-acknowledgement'
$target=Join-Path $directory 'release-brief-limitations.json'
if($Operation -eq 'Write'){
 if(Test-Path $target){throw 'Preserve existing limitation receipt'}
 if(-not $PSCmdlet.ShouldProcess($target,'Retain source and native evidence limitations without tests or edits')){return}
 $receiptPath=Join-Path $directory 'receipt.json';$receipt=Get-Content -Raw $receiptPath|ConvertFrom-Json -Depth 100
 if((Get-FileHash $receipt.plan.path).Hash -cne $receipt.plan.sha256){throw 'Plan hash mismatch'}
 $pins=@(foreach($pin in $receipt.sourceCheck.result.sourcePins){$hash=(Get-FileHash -LiteralPath (Join-Path $workspace $pin.path)).Hash;if($hash -cne $pin.sha256){throw 'Stopped source changed'};[ordered]@{path=$pin.path;sha256=$hash;matchesStoppedSource=$true}})
 $gates=@(foreach($gate in $receipt.gates){
  if((Get-FileHash $gate.path).Hash -cne $gate.sha256 -or (Get-FileHash $gate.result.junit).Hash -cne $gate.result.junitSha256){throw 'Gate receipt/native hash mismatch'}
  $xml=[xml][IO.File]::ReadAllText($gate.result.junit);$cases=@($xml.SelectNodes('//testcase'))
  $failed=@($cases|Where-Object {$_.SelectNodes('failure|error').Count -gt 0}).Count;$skipped=@($cases|Where-Object {$_.SelectNodes('skipped').Count -gt 0}).Count
  if($cases.Count -ne $gate.result.cases -or $failed -ne $gate.result.failed -or $skipped -ne $gate.result.skipped){throw 'Native denominator mismatch'}
  [ordered]@{path=$gate.path;sha256=$gate.sha256;binding=$gate.result.binding;startedAt=$gate.result.startedAt;finishedAt=$gate.result.finishedAt;junit=$gate.result.junit;junitSha256=$gate.result.junitSha256;nativeCases=$cases.Count;nativeFailed=$failed;nativeSkipped=$skipped;nativeRejectCases=@($cases|Where-Object {$_.name -match 'rejects'}).Count;sourcePins=@(foreach($pin in $gate.result.sourcePins){if((Get-FileHash -LiteralPath $pin.copy).Hash -cne $pin.sha256){throw 'Retained gate source mismatch'};[ordered]@{path=$pin.path;sha256=$pin.sha256;retainedCopyMatches=$true}})}
 })
 $extras=@('tests/browser/ui-command-capture.contract.ts','tests/browser/ui-command-capture.test.ts')
 $extraPins=@(foreach($path in $extras){[ordered]@{path=$path;sha256=(Get-FileHash -LiteralPath (Join-Path $workspace $path)).Hash}})
 $limitations=@(
  @{id='ACK-LIMIT-01';source='tests/browser/ui-command-acknowledgement.test.ts:78';claim='Real binding means real pure classifier, own-solve predicate and commit coordinator with scripted ports.';limit='It does not execute readCommandUi, awaitCommandUi or assertPageOwnRoundSolve against a DOM. Actual selectors, ARIA/version attributes, Playwright polling and row extraction first execute in upcoming real browser lanes.'},
  @{id='ACK-LIMIT-02';source='tests/browser/ui-command-acknowledgement.ts:30-75';claim='DOM adapter inspects one scoped panel, busy/version and exact pending control; own-solve adapter verifies a round-captioned scorecard, same-context alias and solved row.';limit='Pure-state tests do not certify selector stability, aria propagation, live scheduling or arbitrary aliases. Existing generated aliases and actual browser assertions must supply that evidence; no general DOM coverage is claimed.'},
  @{id='ACK-LIMIT-03';source='tests/browser/ui-command-capture.ts:40-83';claim='Matrix logical call waits for fresh preparation, validates initial request, retires explicit409, and exact-payload checks uncertain retries within the existing12 attempts.';limit='Acknowledgement hooks are optional for backward compatibility with58 prior cases; that older test pass does not prove all callers use hooks. Current two live adapters were inspected to supply the new hooks. No increased timeout or weakened game assertions was observed.'},
  @{id='ACK-LIMIT-04';source='tests/browser/live-player-counts.integration.spec.ts:60-102,174-195';claim='Sender retirement precedes command return; intended answer and profile are checked; current-round same-context solved state precedes solve increment.';limit='Completed JSON alone is no longer counted. Native actual2..15matrix at the successor frozen head is still required; focused124 cases and old fdee build cannot establish a completed revised matrix.'},
  @{id='ACK-LIMIT-05';source='tests/browser/live-multiplayer.integration.spec.ts:77-115,128-140,297-472';claim='Strict generic command and answer helpers use preparation/acknowledgement; unresolved pending is rejected;4-conflict answer bound and push/read/suppression/privacy assertions remain.';limit='This is source inspection of the adapter, not an executed strict journey. The source-check/adoption diff and focused unit tests are not private-push, renewal, reconnect or observer capacity evidence.'},
  @{id='ACK-LIMIT-06';source='tests/browser/live-player-counts.integration.spec.ts:79-83; tests/browser/live-multiplayer.integration.spec.ts:70-75';claim='New successful-classification observations correlate player, logical action and UUID IDs with response/rendered versions and pending/busy state.';limit='Rejected classifier probes fail before observation callback, so records are not a complete denied/malformed-state history. No browser start/header/completion/abort timestamps or server spans are added. They cannot retroactively identify the old fdee page7request or explain11.6s latency.'},
  @{id='ACK-LIMIT-07';source='docs/evidence/release15/ui-acknowledgement/receipt.json';claim='Original118 gate, V2mock124, coordinator real124 and post-adoption real124 chronology are preserved.';limit='Original118 lacked deferred retirement completion proof; V2added3 positive/3 negative cases before coordinator/adoption changes. Transient direct tsc exit2 and15Biomewarnings are retained. Lint exit0 is not zero-warning evidence. Focused native counts do not substitute for full suites/TRX at new head.'},
  @{id='ACK-LIMIT-08';source='docs/evidence/release15/frozen-fdee7a2/live-ui/runtime-responsiveness-diagnosis.json';claim='Recovery gating addresses the test acknowledgement boundary.';limit='No application responsiveness or latency cause fix is established. Current operational latency, pool/lock/CPU attribution and user-visible recovery behavior remain qualified until next actual browser evidence and optional owned-runtime observations. No new HTTP SLA or timeout/cap/pool/worker increase is authorized.'}
 )
 $data=[ordered]@{recordedAt=[DateTimeOffset]::Now.ToString('o');classification='Read-only same-family release brief assessment, not hostile validation';sessionId='Codex-20261030T194802Z-plugin-session';requestId='req-20261031T000037Z-ui-acknowledgement-limits';parentSessionId='Codex-20261027T100516Z-plugin-session';parentRequestId='req-20261030T203656Z-cline-beam-release';reviewerSelection='Cline Beam High until Monday2November2026; exact cutoff unspecified';plan=@{path=$receipt.plan.path;sha256=$receipt.plan.sha256;readInFull=$true};repairReceipt=@{path=$receiptPath;sha256=(Get-FileHash $receiptPath).Hash;readInFull=$true;sourceStoppedAt=$receipt.sourceStoppedAtLocal;baselineRevision=$receipt.revision;dirtyTestSource=$receipt.dirtyTestSource};stoppedSourceReadback=$pins;supportingSourcePins=$extraPins;nativeGateReadback=$gates;limitations=$limitations;noObservedNewBlockingSourceDefect=$true;qualification='Bounded read-only assessment. No new tests/builds/browser/runtime/provider actions, source/requirement/status mutations or reviewer invocation. This does not authorize a release done state. Existing full applicable suite and independent98/98HV obligations remain.';remainingFail=@('Historical fdee10-player native matrix failure remains retained; fresh revised matrix not evaluated here.');unknown=@('Actual DOM adapter execution on successor candidate.','Full successor build/unit/PG/browser/Realtime/matrix/strict outcomes.','Exact latency and pending-command causal identity.','Independent Cline verdict and full durable reviewer log.');accuracyPercent=99;completenessPercent=98;ratingBasis='Full requested plan/receipt and adopted sources read; stopped source/native gate hashes and counts checked. Runtime and independent-review claims deliberately excluded.';writer=@{sha256=(Get-FileHash $PSCommandPath).Hash;source=[IO.File]::ReadAllText($PSCommandPath)}}
 $data|ConvertTo-Json -Depth 100|Set-Content $target
 $response=(@((Get-Date -Format s)+' - Read-only acknowledgement follow-up: '+$target+' SHA256 '+(Get-FileHash $target).Hash+'. All6stopped source pins and4native gate reports hash/count readback match. Focused final124cases are66new(33positive/33negative)+58prior; zero failed/skipped. Real binding exercises pure state/solve predicates and commit coordinator, not actual DOM readers/polling/selectors. Upcoming existing native browser lanes are the first execution of those adopted DOM functions. Source-only checks show current matrix hooks and strict preparation/acknowledgement with unchanged retry bounds; they do not establish actualUI/privatepush/latency/release/HV.', 'Retain limitations ACK-LIMIT-01 through08 in the next Cline brief. Original118gap, V2extension, transient tsc2and15Biomewarnings remain disclosed. No new blocking source defect observed in this bounded read, but historical matrix failure and all successor runtime outcomes remain unverified. Exact pending-command/latency attribution and independent Cline verdict are UNKNOWN. No tests, builds or application edits performed. Accuracy99percent, completeness98percent for this bounded evidence assessment, not a hostile approval. Session Codex-20261030T194802Z-plugin-session / req-20261031T000037Z-ui-acknowledgement-limits.') -join "`n")
 [IO.File]::WriteAllText('/tmp/wordpairs-acknowledgement-limitations-result.txt',$response)
 [pscustomobject]@{path=$target;sha256=(Get-FileHash $target).Hash;sourcePins=$pins.Count;nativeReports=$gates.Count;limitations=$limitations.Count}|ConvertTo-Json
}else{
 $plugin='<home>/.codex/plugins/cache/mcpserver-codex-plugin/mcpserver/1.121.0';$base=@{WorkspacePath=$workspace;CacheRoot='/tmp/wordpairs-release-audit-20261030';PluginRoot=$plugin}
 $response=[IO.File]::ReadAllText('/tmp/wordpairs-acknowledgement-limitations-result.txt')
 $decision='Treat124isolated native cases as classifier/coordinator evidence, not actual DOM/live journey or latency proof. Carry rejected-probe history, compatibility hooks, actual adapter execution and full successor evidence limits into Cline brief. Preserve historical failures, mockV1gap, V2chronology, transient tsc2and15Biomewarnings; no new gates or source changes.'
 & (Join-Path $plugin 'Invoke-CodexMcpPlugin.ps1') @base -Command Invoke -Method 'workflow.sessionlog.appendDialog' -ParamsObject @{dialogItems=@(@{timestamp=[DateTimeOffset]::Now.ToString('o');role='model';category='decision';content=$decision},@{timestamp=[DateTimeOffset]::Now.ToString('o');role='model';category='observation';content=$response})}
 & (Join-Path $plugin 'Invoke-CodexMcpPlugin.ps1') @base -Command Invoke -Method 'workflow.sessionlog.appendActions' -ParamsObject @{actions=@(@{order=1;type='read';status='completed';filePath='docs/evidence/release15/ui-acknowledgement/plan.md';description='Read full final plan and522-line consolidated receipt, new classifier/DOM helper, contract/mock provider/coordinator and both full adopted browser specs. Independently check stopped source/native gate hashes and nativeJUnit counts without test execution.'},@{order=2;type='design_decision';status='completed';filePath='';description=$decision},@{order=3;type='create';status='completed';filePath=$target;description='Retain eight evidence-bound brief limitations, native/source pins, full writer bytes, and all remaining failures/unknowns. No source or requirements changes.'})}
 & (Join-Path $plugin 'Invoke-CodexMcpPlugin.ps1') @base -Command CompleteTurn -Response $response
}
